3	import java.util.List;
4	import java.util.Locale;
5	import java.util.Set;
6	import java.util.regex.Pattern;
7	
8	import net.officefloor.plugin.variable.Val;
9	import org.springframework.samples.petclinic.model.Owner;
10	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
11	
12	/**
13	 * Email is optional: a missing (null/blank) value is left untouched. When present it must be a
14	 * syntactically valid address, otherwise the request is rejected 400 via
15	 * {@link MissingOwnerFieldsException}. A valid value is lower-cased in place, so later steps save
16	 * and return it as {@code email}.
17	 */
18	public class NormalizeOwnerEmail {
19	
20	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
21	
22	    private static final Set<String> DISPOSABLE_DOMAINS =
23	            Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
24	
25	    public void service(@Val Owner owner) throws MissingOwnerFieldsException {
26	        String email = owner.getEmail();
27	        if (email == null || email.isBlank()) {
28	            return;
29	        }
30	        if (!EMAIL.matcher(email).matches()) {
31	            throw new MissingOwnerFieldsException(List.of("email"));
32	        }
33	        String normalized = email.toLowerCase(Locale.ROOT);
34	        if (DISPOSABLE_DOMAINS.contains(normalized.substring(normalized.lastIndexOf('@') + 1))) {
35	            throw new MissingOwnerFieldsException(List.of("email"));
36	        }
37	        owner.setEmail(normalized);
38	    }
39	}
