16	    public static String of(Owner owner) {
17	        String e164 = owner.getTelephone();
18	        if (e164 == null || !e164.startsWith("+")) {
19	            return e164;
20	        }
21	        String digits = e164.substring(1);
22	        int countryCodeLength = digits.startsWith("61") ? 2 : 1;
23	        String national = digits.substring(countryCodeLength);
24	        StringBuilder grouped = new StringBuilder();
25	        for (int i = 0; i < national.length(); i++) {
26	            if (i > 0 && i % 3 == 0) {
27	                grouped.append(' ');
28	            }
29	            grouped.append(national.charAt(i));
30	        }
31	        return "+" + digits.substring(0, countryCodeLength) + " " + grouped;
32	    }
33	}
