2	
3	import java.util.Map;
4	import java.util.concurrent.ConcurrentHashMap;
5	
6	import net.officefloor.server.http.HttpHeader;
7	import net.officefloor.server.http.ServerHttpConnection;
8	
9	/**
10	 * Remembers the owner id created for each seen {@code Idempotency-Key}, so a create that repeats
11	 * with an already-seen key returns the originally created owner instead of creating a duplicate.
12	 */
13	public final class IdempotencyStore {
14	
15	    private static final String HEADER = "Idempotency-Key";
16	
17	    private static final Map<String, Integer> BY_KEY = new ConcurrentHashMap<>();
18	
19	    private IdempotencyStore() {
20	    }
21	
22	    /** The request's {@code Idempotency-Key} header value, or {@code null} when absent. */
23	    static String keyOf(ServerHttpConnection connection) {
24	        HttpHeader header = connection.getRequest().getHeaders().getHeader(HEADER);
25	        return header == null ? null : header.getValue();
26	    }
27	
28	    /** The owner id previously created under {@code key}, or {@code null} if none (or key null). */
29	    static Integer find(String key) {
30	        return key == null ? null : BY_KEY.get(key);
31	    }
32	
33	    /** Remember {@code ownerId} under {@code key} on first use; a no-op when {@code key} is null. */
34	    static void record(String key, int ownerId) {
35	        if (key != null) {
36	            BY_KEY.putIfAbsent(key, ownerId);
37	        }
38	    }
39	}
