8	/**
9	 * Caps an owner's {@link MembershipLevel} at one above the highest level among the OTHER members of
10	 * its {@link HouseholdId household}. Levels are at least 1, so a maximum of 0 means the owner has no
11	 * existing household member and the level is returned unchanged (no cap applies).
12	 */
13	public final class HouseholdLevelCeiling {
14	
15	    private HouseholdLevelCeiling() {
16	    }
17	
18	    public static int cap(Owner owner, int membershipLevel, OwnerRepository repository) {
19	        String householdId = HouseholdId.of(owner);
20	        int max = 0;
21	        for (Owner other : repository.findAll()) {
22	            if (!Objects.equals(other.getId(), owner.getId()) && householdId.equals(HouseholdId.of(other))) {
23	                max = Math.max(max, MembershipLevel.of(MembershipPoints.of(other,
24	                        NamesakeCount.of(other, repository), HouseholdSize.of(other, repository))));
25	            }
26	        }
27	        return max == 0 ? membershipLevel : Math.min(membershipLevel, max + 1);
28	    }
29	}
